-- =====================================================================
-- GalleryBetak E-Commerce - Elghazawy Kitchen Tools Seed Data
-- Source: https://elghazawy.com/ar/sub-category/kitchen-tools
-- Products: 500
-- Execute AFTER 01_DDL_Schema.sql
-- =====================================================================

SET NOCOUNT ON;

DECLARE @KitchenCategoryId INT;

DELETE PT FROM [dbo].[ProductTags] PT INNER JOIN [dbo].[Products] P ON P.[Id] = PT.[ProductId] WHERE P.[SKU] LIKE N'ELG-%' OR P.[SKU] IN (N'SKU001', N'SKU002', N'SKU003', N'SKU004', N'SKU005', N'SKU006', N'SKU007', N'SKU008', N'SKU009', N'SKU010');
DELETE PI FROM [dbo].[ProductImages] PI INNER JOIN [dbo].[Products] P ON P.[Id] = PI.[ProductId] WHERE P.[SKU] LIKE N'ELG-%' OR P.[SKU] IN (N'SKU001', N'SKU002', N'SKU003', N'SKU004', N'SKU005', N'SKU006', N'SKU007', N'SKU008', N'SKU009', N'SKU010');
DELETE FROM [dbo].[Products] WHERE [SKU] LIKE N'ELG-%' OR [SKU] IN (N'SKU001', N'SKU002', N'SKU003', N'SKU004', N'SKU005', N'SKU006', N'SKU007', N'SKU008', N'SKU009', N'SKU010');
DELETE FROM [dbo].[Categories] WHERE [Slug] IN (N'home-furniture', N'decorations', N'lighting', N'rugs', N'textiles') AND NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [CategoryId] = [dbo].[Categories].[Id]);

IF NOT EXISTS (SELECT 1 FROM [dbo].[Categories] WHERE [Slug] = N'kitchen-tools')
BEGIN
    INSERT INTO [dbo].[Categories] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [ImageUrl], [ParentId], [DisplayOrder], [IsActive]) VALUES (N'أدوات ومعدات المطبخ', N'Kitchen Tools', N'kitchen-tools', N'منتجات أدوات ومعدات المطبخ المستوردة من الغزاوي.', N'Kitchen tools and equipment imported from Elghazawy.', N'https://elghazawy.com/front_assets/img/logo-large.png', NULL, 1, 1);
END;

SELECT @KitchenCategoryId = [Id] FROM [dbo].[Categories] WHERE [Slug] = N'kitchen-tools';

