INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'ميزان مطبخ رقمي، 5 كجم، شاشة LCD، فضي، 1046', N'Digital kitchen scale, 5 kg, LCD display, silver, 1046', N'digital-kitchen-scale-5-kg-lcd-display-silver-1046-38074270297753', N'الميزان الأكثر دقة، كما أنه سهل الاستخدام، ميزان الطعام الرقمي المصمم بنظام مستشعر دقيق ليمنحك وزن دقيق طوال الوقت، سعة 11 رطل - 5 كجم، ميزان مثالي للطعام واللحوم والمجوهرات والعلاج والمراسلات والخبز ومكونات الطهي بدقة محسّنة.شاشة لمس رقمية لعرض الوزن، شاشة LCD قابلة للقراءة ، سهولة التحويل بين وحدات القياس (كجم ، رطل، اونصة، مل) بالضغط على زر الوحدة ، إيقاف تلقائي بعد دقيقتين للحفاظ على طاقة البطارية وكفاءتها، يستخدم بطاريتين AAA.ميزان رقمي صغير وانيق- تم تصميم ميزان الطعام ليأخذ أقل مساحة على مكتبك مع سهولة التخزين والحمل علاوة على كونه خفيف الوزن. تقنية المضادة للبصمات لسهولة التنظيف والصيانة.تصميم سطح من الستانلس ستيل مضاد للبصمات والخدوش لتسهيل التنظيف والصيانة، ووزن الطعام بطريقة ذكية.', N'Digital kitchen scale, 5 kg, LCD display, silver, 1046', 260.00, NULL, N'ELG-38074270297753', 30, @KitchenCategoryId, 1, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270297753/Digital+kitchen+scale%2C+5+kg%2C+LCD+display%2C+silver%2C+1046', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270297753');
