INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'طقم تنظيف أواني 5 قطع، ألوان متعددة', N'Dishwashing Set 5-Piece, Assorted Colors', N'dishwashing-set-5-piece-assorted-colors-38074270299226', N'اسم المنتج • طقم تنظيف المطبخ المتكامل (Clean Value Combo Set) – 5 قطع الوصف • اجعل عملية تنظيف الأواني والمطبخ أكثر سهولة وسرعة مع هذا الطقم الاقتصادي والمتكامل • يحتوي على خمس أدوات أساسية مصممة للتعامل مع مختلف أنواع الأسطح والأواني، من الصحون الرقيقة إلى المقالي شديدة الاتساخ مكونات الطقم • فرشاة تنظيف بمقبض طويل: تصميم مريح يساعد على الوصول لعمق الأواني وحماية اليدين من ملامسة المنظفات مباشرة • ليفة سلك (ستانلس ستيل): مثالية لإزالة الدهون الصعبة وبقايا الطعام المحترق من الحلل والمقالي غير الحساسة • إسفنجة تنظيف ناعمة: مخصصة للأواني والأسطح الرقيقة التي تحتاج إلى تنظيف لطيف بدون خدوش • فوطة مطبخ (مايكروفايبر/قماش): عالية الامتصاص لتجفيف الأواني وتلميع الأسطح مثل الرخام • قطعة تنظيف إضافية: لتوفير استخدامات متعددة وتغطية احتياجات التنظيف اليومية المميزات • جودة عالية تتحمل الاستخدام اليومي المكثف • متعدد الاستخدامات لتنظيف الصحون والأواني والبوتاجاز وأحواض المطبخ • تصميم عملي ومنظم داخل عبوة واحدة سهلة التخزين • متوفر بألوان مبهجة مثل الوردي والأزرق لإضفاء لمسة حيوية على المطبخ', N'Dishwashing Set 5-Piece, Assorted Colors', 55.00, NULL, N'ELG-38074270299226', 30, @KitchenCategoryId, 1, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270299226/Dishwashing+Set+5-Piece%2C+Assorted+Colors', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270299226');
