INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'ميزان مطبخ كاميري 5 كيلو مؤشر ميكانيكي طبق ستانلس ستيل- ألوان متعددة', N'CAMRY 5kg Kitchen Scale with Mechanical Indicator and Stainless Steel Platform - Multiple Colors', N'camry-5kg-kitchen-scale-with-mechanical-indicator-and-stainless-steel-platform-multiple-colors-38074270300376', N'اسم المنتج • ميزان مطبخ CAMRY NR-5KG بمؤشر ميكانيكي العلامة التجارية • الماركة: CAMRY • نوع المنتج: ميزان مطبخ ميكانيكي بمؤشر • السعة القصوى: 5 كجم الخامات والتصميم • تصميم كلاسيكي أنيق باللون الأحمر • هيكل معدني متين لتحمل الاستخدام اليومي • طبق علوي من الستانلس ستيل المقاوم للصدأ • قاعدة ثابتة لثبات أفضل أثناء الوزن • واجهة دائرية كبيرة لسهولة قراءة القياسات الأداء والدقة • مؤشر ميكانيكي عالي الوضوح • قياس دقيق للأوزان حتى 5 كجم • تدريج واضح بالجرام والكيلوجرام • يعمل بدون بطاريات أو كهرباء المميزات • سهل الاستخدام والتنظيف • مناسب للاستخدام اليومي في المطبخ • تصميم عملي يوفر قراءة سريعة للوزن • حجم مدمج مناسب للمطابخ المنزلية الاستخدامات • مناسب لوزن الخضروات والفواكه واللحوم • مثالي لتحضير وصفات الطهي والخبز • مناسب لوزن المكونات والتوابل بدقة محتويات العبوة • ميزان CAMRY NR-5KG • طبق ستانلس ستيل علوي للوزن', N'CAMRY 5kg Kitchen Scale with Mechanical Indicator and Stainless Steel Platform - Multiple Colors', 810.00, NULL, N'ELG-38074270300376', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270300376/CAMRY+5kg+Kitchen+Scale+with+Mechanical+Indicator+and+Stainless+Steel+Platform+-+Multiple+Colors', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270300376');
