INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'ميزان مطبخ كاميري 10 كيلو مؤشر ميكانيكي طبق ستانلس ستيل- ألوان متعددة', N'CAMRY 10kg Kitchen Scale with Mechanical Indicator and Stainless Steel Platform - Multiple Colors', N'camry-10kg-kitchen-scale-with-mechanical-indicator-and-stainless-steel-platform-multiple-colors-38074270300380', N'اسم المنتج • ميزان مطبخ CAMRY NR-10KG بمؤشر ميكانيكي العلامة التجارية • الماركة: CAMRY • نوع المنتج: ميزان مطبخ ميكانيكي بمؤشر • السعة القصوى: 10 كجم الخامات والتصميم • تصميم كلاسيكي عملي باللون الأحمر • هيكل معدني متين يتحمل الاستخدام اليومي • طبق علوي من الستانلس ستيل المقاوم للصدأ • قاعدة ثابتة لثبات أفضل أثناء الوزن • واجهة دائرية كبيرة بمؤشر واضح لسهولة قراءة القياسات الأداء والدقة • مؤشر ميكانيكي عالي الوضوح • قياس دقيق للأوزان حتى 10 كجم • تدريج واضح بالجرام والكيلوجرام • يعمل بدون بطاريات أو كهرباء • مناسب لوزن الكميات الكبيرة والمتوسطة بدقة المميزات • سهل الاستخدام والتنظيف • مناسب للاستخدام اليومي في المطابخ المنزلية • تصميم عملي لقراءة الوزن بسرعة وسهولة • حجم مناسب مع قدرة تحمل أعلى للأوزان الاستخدامات • مناسب لوزن الخضروات والفواكه واللحوم • مثالي لتحضير وصفات الطهي والخبز • مناسب لوزن الدقيق والسكر والمكونات المختلفة • عملي للاستخدام المنزلي والمطاعم الصغيرة محتويات العبوة • ميزان CAMRY NR-10KG • طبق ستانلس ستيل علوي للوزن', N'CAMRY 10kg Kitchen Scale with Mechanical Indicator and Stainless Steel Platform - Multiple Colors', 830.00, NULL, N'ELG-38074270300380', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270300380/CAMRY+10kg+Kitchen+Scale+with+Mechanical+Indicator+and+Stainless+Steel+Platform+-+Multiple+Colors', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270300380');
