INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'ميزان ذكي رقمي من يوفي C1 ، اقصى وزن 180 كجم، أسود، T9146H11', N'Eufy C1 Digital Smart Scale, 180 Kg, Black, T9146H11', N'eufy-c1-digital-smart-scale-180-kg-black-t9146h11-38074270283717', N'الصحة الشاملة: تعلم على الفور 12 قياسًا ثاقبًا لصحة جسمك.تطبيق Eufylife المجاني وتطبيقات الطرف الثالث: تتبع قياساتك على Apple Health وGoogle Fit وFitbit.تم تحسين الدقة بنسبة 10%: يضمن زوجان من أجهزة الاستشعار فائقة الحساسية على شكل حرف G قياسات أكثر دقة.لجميع أفراد الأسرة: تتبع الاتجاهات الصحية لما يصل إلى 16 مستخدمًا من حساب واحد، والتعرف على كل عضو تلقائيًا.تحميك اللوحة العلوية الزجاجية المستديرة من الاصطدام بالحواف المدببة.تضمن اللوحة العلوية المضادة للانزلاق والتصميم المنخفض والمستقر الثبات عند الوقوف.قم بالتبديل من الجنيه إلى الكيلوجرام والعودة في ثانية واحدة.يعني النقل اللاسلكي السريع للبيانات أنه يمكنك عرض قياساتك في ثوانٍ.اطلع على جميع البيانات التاريخية لتقدمك واتجاهاتك الصحية بسهولة.يتميز ميزان Eufy Smart Scale C1 بالذكاء الكافي لمطابقة القياسات مع ملف تعريف المستخدم الصحيح تلقائيًا.اتصال بلوتوثتطبيق Eufylife المجاني وتطبيقات الطرف الثالث: تتبع قياساتك على Apple Health وGoogle Fit وFitbit.لوحة زجاجية مستديرة آمنة، تصميم ثابت12 قياسًا ثاقبًا لصحة جسمك.زوجان من أجهزة الاستشعار فائقة الحساسية على شكل حرف G', N'Eufy C1 Digital Smart Scale, 180 Kg, Black, T9146H11', 1299.00, NULL, N'ELG-38074270283717', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270283717/Eufy+C1+Digital+Smart+Scale%2C+180+Kg%2C+Black%2C+T9146H11', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270283717');
