INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'طقم ثلاجة ويفر من ميدستار، مربع صغير ،3 قطع، آمن للإستخدام في الميكروويف، خالي من BPA، أزرق', N'Midstar Wafer Refrigerator Set, Small Square, 3 Pieces, Microwave Safe, BPA Free, Blue', N'midstar-wafer-refrigerator-set-small-square-3-pieces-microwave-safe-bpa-free-blue-38074270274302', N'العلامة التجارية: Medstar.الموديل: ويفر (Wafer).العدد: 3 قطع بحجم عملي لتلبية مختلف احتياجات التخزين.التصميم: مربع صغير، يوفر مساحة استيعابية ممتازة وسهولة في الترتيب فوق بعضها لتوفير المساحة.اللون: غطاء باللون الأزرق الأنيق مع حاوية شفافة تتيح لك رؤية المحتوى الداخلي بسهولة دون الحاجة لفتحها.حجم علب الثلاجه ٠.٧٥ لترالمميزات والخصائص الصحيةمواد آمنة صحياً (BPA Free): الطقم خالي تماماً من مادة البيسفينول أ (BPA)، مما يجعله آمناً بنسبة 100% لملامسة الطعام.ملائم للأستخدام في الميكروويف: يمكنك تسخين وجباتك بكل سهولة وأمان داخل الميكروويف (ملاحظة: يجب إزالة الغطاء قبل إدخاله للميكروويف).بلاستيك نقي: مصنوع من مواد بلاستيكية نقية وغير معادة التدوير نهائياً (100% None-Recycled) لضمان أعلى معايير الجودة وسلامة الغذاء.مقاومة للحرارة (سخن وبارد): يتحمل درجات الحرارة المتفاوتة بكفاءة، بدءاً من -10 درجات مئوية للتجميد، وحتى +110 درجة مئوية للأطعمة الساخنة.سهل التنظيف: آمن تماماً للاستخدام في غسالة الأطباق، مما يوفر عليك الوقت والمجهود.', N'Midstar Wafer Refrigerator Set, Small Square, 3 Pieces, Microwave Safe, BPA Free, Blue', 65.00, NULL, N'ELG-38074270274302', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270274302/Midstar+Wafer+Refrigerator+Set%2C+Small+Square%2C+3+Pieces%2C+Microwave+Safe%2C+BPA+Free%2C+Blue', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270274302');
