INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'علبة ثلاجة اكريلك مقسم ، بيج ، 14-163', N'Divided Acrylic Fridge Tray, Beige, 14-163', N'divided-acrylic-fridge-tray-beige-14-163-38074270292337', N'تصميم صينية التقديم المُقسّمة بغطاء مع فواصل قابلة للإزالة يضمن عدم تلامس الطعام تتسع كل حجرة للكمية المناسبة من الوجبات الخفيفة والحلويات والفواكه والمكسرات والتوابل، إلخ يُمكنك أيضًا إزالة الحجرات لتخزين أغراض أكبر، حيث يُسهّل التصميم القابل للإزالة إعادة تعبئة أو تنظيف الحاويات الفردية صينية التقديم المحمولة ذات الغطاء المُحكم مصنوعة من الاكليرك صالح للطعام، والعلبة الخارجية الشفافة مصنوعة من مادة البولي إيثيلين تيرفثالات (PET)، والحجرات الداخلية الأربعة البيضاء والمقابض مصنوعة من مادة البولي بروبيلين طبق الوجبات الخفيفة المُقسّم بغطاء متين للاستخدام طويل الأمد', N'Divided Acrylic Fridge Tray, Beige, 14-163', 230.00, NULL, N'ELG-38074270292337', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270292337/Divided+Acrylic+Fridge+Tray%2C+Beige%2C+14-163', SYSUTCDATETIME()
