INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'حافظة طعام بلاستيك، تيتيز ريفر، سعة 650 مل، ألوان متعدد، موديل AP‑9037', N'Plastic Food Container Titiz River, 650ml Capacity, Multi-Colored, Model AP-9037', N'plastic-food-container-titiz-river-650ml-capacity-multi-colored-model-ap-9037-38074270295695', N'اسم المنتج • حاوية تخزين طعام – Titiz AP‑9037 العلامة التجارية • Titiz نوع المنتج • حاوية بلاستيكية لتخزين الأطعمة الخامات والتصنيع • مصنوعة من بلاستيك غذائي متين وآمن للاستخدام مع الأطعمة • تصميم بسيط وعملي يناسب الاستخدام اليومي السعة والحجم • السعة: 0.65 لتر • الأبعاد: • الطول: حوالي 16.5 سم • العرض: حوالي 11.5 سم • الارتفاع: حوالي 5.5 سم الخصائص التشغيلية • مناسبة لتخزين الأطعمة والمأكولات بكمية صغيرة إلى متوسطة • تصميم خفيف الوزن وسهل الحمل • تأتي مع غطاء محكم الإغلاق للحفاظ على المحتوى طازجًا الألوان المتوفرة • ألوان متنوعة تشمل البنفسجي، الوردي، التركوازي (قد يختلف التوفر حسب المخزون) مجالات الاستخدام • تخزين الأطعمة في المنزل • مثالية لنقل الوجبات الصغيرة إلى العمل أو المدرسة • مناسبة لحفظ بقايا الطعام في الثلاجة العناية والتنظيف • سهلة التنظيف بعد الاستخدام • يُفضّل غسيلها يدويًا أو في غسالة الأطباق إذا كانت المادة مقاومة لذلك • احفظها في مكان جاف ونظيف بعد التجفيف', N'Plastic Food Container Titiz River, 650ml Capacity, Multi-Colored, Model AP-9037', 80.00, NULL, N'ELG-38074270295695', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270295695/Plastic+Food+Container+Titiz+River%2C+650ml+Capacity%2C+Multi-Colored%2C+Model+AP-9037', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270295695');
