INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'طقم علب ثلاجه بلاستيك دائري 3 قطع ، الوان ، 478-124813', N'3-piece Round Plastic Refrigerator Container Set, Assorted Colors, 478-124813', N'3-piece-round-plastic-refrigerator-container-set-assorted-colors-478-124813-38074270297326', N'تحتوي العبوة على 3 علب تخزين دائرية بتصميم متطابق مع أغطية خضراء ، مثالية لتخزين كميات صغيرة من الطعام أو الوجبات الخفيفة. صممنا العلب ليتم رصها بأناقة فوق بعضها البعض، مما يساعد على زيادة مساحة التخزين في الخزائن والثلاجات. تتميز كل علبة بغطاء محكم يساعد على الحفاظ على الطعام طازجًا ويحمي من الانسكابات أثناء النقل أو التخزين. مثالية لتخزين ما تبقى من الطعام أو وجبات الغداء المعبأة أو تنظيم أدوات المطبخ الصغيرة ومناسبة لتخزين الثلاجة والمخزن. علب دائرية صغيرة الحجم بحجم مثالي للوجبات الفردية، مما يجعلها مريحة لاحتياجات تخزين الطعام اليومية.', N'3-piece Round Plastic Refrigerator Container Set, Assorted Colors, 478-124813', 115.00, NULL, N'ELG-38074270297326', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270297326/3-piece+Round+Plastic+Refrigerator+Container+Set%2C+Assorted+Colors%2C+478-124813', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270297326');
