INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'طقم علب ثلاجة كولمبو مد ستار، 5 قطع، أحجام متنوعة، خالي من مادة BPA', N'Colombo Med Star Refrigerator Container Set, 5 Pieces, Assorted Sizes, BPA Free', N'colombo-med-star-refrigerator-container-set-5-pieces-assorted-sizes-bpa-free-38074270297377', N'وصف منتج: طقم ثلاجة كولومبو من "مدستار" (5 قطع)نظم مطبخك وثلاجتك بفعالية وأمان مع طقم علب ثلاجة كولومبو (Colombo Set) المقدم من شركة مدستار (Medstar).يتميز هذا الطقم بتصميم عملي يجمع بين الجودة العالية والألوان الجذابة لتلبية كافة احتياجات التخزين اليومية، مع الحفاظ على طعامك طازجاً وصحياً.المميزات للمنتج:تنوع الأحجام: يضم الطقم 5 علب بأحجام متدرجة لتناسب تخزين مختلف أنواع الأطعمة، بدءاً من الوجبات الخفيفة والحلويات وحتى المخبوزات والكميات الكبيرة.آمن صحياً (BPA Free): العلب مصنوعة من بلاستيك نقي وخالية تماماً من مادة البيسفينول أ، ومصنعة من مواد أولية خالية من الرصاص لضمان أعلى معايير الأمان لأسرتك.تصميم ذكي: تأتي العلب بجسم شفاف يتيح لك رؤية المحتوى بسهولة دون الحاجة لفتحها، مع أغطية محكمة الغلق بألوان مبهجة (أزرق، أخضر، أصفر، برتقالي، بنفسجي).توفير المساحات: تصميم العلب يسمح بتداخلها معاً (رصها داخل بعضها) عند عدم الاستخدام، مما يوفر مساحة تخزين قيمة في دواليب المطبخ.ضمان الجودة: يأتي المنتج مع ضمان لمدة عام كامل من الشركة المصنعة لضمان رضاك.سعة أحجام العلب (من الأصغر للأكبر):العلبة الأولى: 0.750 لترالعلبة الثانية: 1.250 لترالعلبة الثالثة: 1.750 لترالعلبة الرابعة: 2.250 لترالعلبة الخامسة: 3.250 لتر', N'Colombo Med Star Refrigerator Container Set, 5 Pieces, Assorted Sizes, BPA Free', 175.00, NULL, N'ELG-38074270297377', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270297377/Colombo+Med+Star+Refrigerator+Container+Set%2C+5+Pieces%2C+Assorted+Sizes%2C+BPA+Free', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270297377');
