INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'علبة تخزين اسبانيول الوطنية مع مصفاة، مقاس 2، سعة 3 لتر، شفاف', N'El Watania Espanyol storage box with strainer, size 2, 3 liter capacity, transparent', N'el-watania-espanyol-storage-box-with-strainer-size-2-3-liter-capacity-transparent-38074270298026', N'استمتع بتجربة تخزين مثالية مع علبة أسبانيول 2 من "الوطنية"، المصممة خصيصاً لتجمع بين الحفظ المحكم وسهولة الاستخدام بفضل نظام المصفاة الداخلي المبتكر.تصميم ذكي بالمصفاة: مزودة بمصفاة داخلية بمقبض علوي، تسمح لك برفع الزيتون أو المخللات من السوائل بسهولة دون الحاجة لاتساخ يديك، مما يضمن بقاء المحتوى طازجاً لفترة أطول.نظام إغلاق محكم: تكنولوجيا غلق متطورة تمنع تسرب الهواء أو الروائح، مما يحافظ على نكهة الطعام الأصلية ويمنع انسكاب السوائل داخل الثلاجة.سعة مثالية: تأتي بسعة 3 لتر، وهي مساحة ممتازة لتخزين كميات وافرة من الزيتون، المخللات، أو حتى حفظ الخضروات الورقية المصفاة.خامة فائقة الجودة: مصنوعة من مواد بلاستيكية آمنة على الغذاء، شفافة تماماً لتسمح لك برؤية المحتوى بوضوح، مع متانة عالية تتحمل الاستخدام اليومي.أبعاد دقيقة: تصميم انسيابي بارتفاع 19 سم وقطر 15 سم، مما يجعلها موفرة للمساحة ومنظمة جداً داخل أرفف الثلاجة.', N'El Watania Espanyol storage box with strainer, size 2, 3 liter capacity, transparent', 71.00, NULL, N'ELG-38074270298026', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270298026/El+Watania+Espanyol+storage+box+with+strainer%2C+size+2%2C+3+liter+capacity%2C+transparent', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270298026');
