INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'علبة تخزين اسبانيول الوطنية مع مصفاة، مقاس 1، سعة 1.85 لتر، شفاف', N'El Watania Espanyol storage box with strainer, size 1, 1.85 liter capacity, transparent', N'el-watania-espanyol-storage-box-with-strainer-size-1-1-85-liter-capacity-transparent-38074270298037', N'استمتع بتجربة تخزين مثالية مع علبة أسبانيول 1 من "الوطنية"، المصممة خصيصاً لتجمع بين الحفظ المحكم وسهولة الاستخدام بفضل نظام المصفاة الداخلي المبتكر.تصميم ذكي بالمصفاة: مزودة بمصفاة داخلية بمقبض علوي، تسمح لك برفع الزيتون أو المخللات من السوائل بسهولة دون الحاجة لاتساخ يديك، مما يضمن بقاء المحتوى طازجاً لفترة أطول.نظام إغلاق محكم: تكنولوجيا غلق متطورة تمنع تسرب الهواء أو الروائح، مما يحافظ على نكهة الطعام الأصلية ويمنع انسكاب السوائل داخل الثلاجة.سعة مثالية: تأتي بسعة 1.85 لتر، وهي مساحة ممتازة لتخزين كميات وافرة من الزيتون، المخللات، أو حتى حفظ الخضروات الورقية المصفاة.خامة فائقة الجودة: مصنوعة من مواد بلاستيكية آمنة على الغذاء، شفافة تماماً لتسمح لك برؤية المحتوى بوضوح، مع متانة عالية تتحمل الاستخدام اليومي.أبعاد دقيقة: تصميم انسيابي بارتفاع 17 سم وقطر 13 سم، مما يجعلها موفرة للمساحة ومنظمة جداً داخل أرفف الثلاجة.', N'El Watania Espanyol storage box with strainer, size 1, 1.85 liter capacity, transparent', 59.00, NULL, N'ELG-38074270298037', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270298037/El+Watania+Espanyol+storage+box+with+strainer%2C+size+1%2C+1.85+liter+capacity%2C+transparent', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270298037');
