INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'طقم ثلاجة بلاستيك زهران 3 قطع، مربع الشكل، لون شفاف', N'Zahran 3-Piece Plastic Refrigerator Set, Square Shape, Transparent Color', N'zahran-3-piece-plastic-refrigerator-set-square-shape-transparent-color-38074270298211', N'اسم المنتج • طقم ثلاجة 3 قطع مربع زهران العلامة التجارية • Zahran (زهران) نوع المنتج • طقم حافظات طعام للثلاجة عدد القطع • 3 حافظات مربعة السعات • 0.5 لتر • 1 لتر • 1.6 لتر المواد الأساسية • بلاستيك عالي الجودة • خالٍ من مادة BPA وآمن للاستخدام مع الطعام التصميم والهيكل • تصميم مربع لاستغلال المساحة داخل الثلاجة بشكل أفضل • حواف مستقيمة تسمح برص الحافظات بجانب بعضها دون هدر مساحة • تصميم يسمح بوضع الحافظات داخل بعضها عند عدم الاستخدام لتوفير مساحة التخزين الأحجام والاستخدام • الحافظة الصغيرة: مناسبة للجبن الأبيض، الزيتون، أو الثوم المقشر • الحافظة المتوسطة: مناسبة للخضروات المقطعة، اللحوم الباردة، أو بقايا الطعام • الحافظة الكبيرة: مناسبة للفواكه، المخبوزات، أو الوجبات المطبوخة اللون والمظهر الخارجي • شفافة بدرجة عالية (Crystal Clear) لسهولة رؤية المحتويات الأغطية • أغطية محكمة الغلق للمساعدة على تقليل دخول الهواء • تصميم بزاوية بارزة لتسهيل الفتح الخصائص والاستخدام • مناسبة لتنظيم الطعام داخل الثلاجة • يمكن استخدامها في الفريزر لتجميد الأطعمة الصغيرة • مناسبة للاستخدام خارج الثلاجة كعلب وجبات خفيفة أو لحفظ التوابل والبقوليات • تساعد على تنظيم الثلاجة والمطبخ بشكل أفضل سهولة التنظيف • آمنة للاستخدام في غسالة الأطباق • تصميم بزوايا انسيابية يسهل تنظيفها يدوياً', N'Zahran 3-Piece Plastic Refrigerator Set, Square Shape, Transparent Color', 330.00, NULL, N'ELG-38074270298211', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270298211/Zahran+3-Piece+Plastic+Refrigerator+Set%2C+Square+Shape%2C+Transparent+Color', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270298211');
