INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'طقم ثلاجة بلاستيك الوطنية ماستر لاين، 3 قطع، مربع الشكل، ألوان متعددة', N'El-Watania Master Line Plastic Refrigerator Set, 3 Pieces, Square Shape, Multi-Color', N'el-watania-master-line-plastic-refrigerator-set-3-pieces-square-shape-multi-color-38074270299397', N'طقم ثلاجة الوطنية "ماستر لاين" المربع – 3 قطع الأناقة والعملية في قطعة واحدة لتنظيم مطبخ عصري! ارتقِ بمستوى تخزين الطعام مع طقم "ماستر لاين" من الوطنية، الذي يتميز بتصميمه المضلع العصري ولونه الأبيض الراقي، ليكون إضافة أنيقة داخل ثلاجتك مع الحفاظ على طزاجة الأطعمة لفترة أطول. المميزات • خامة آمنة صحياً (BPA Free): مصنوع من بلاستيك عالي الجودة وخالي تماماً من مادة BPA لضمان سلامة الاستخدام الغذائي • آمن للفريزر: يتحمل درجات الحرارة المنخفضة، مناسب لتجميد اللحوم والخضروات والوجبات الجاهزة • تصميم موفر للمساحة: شكل مربع ذكي يتيح تداخل العلب داخل بعضها أو رصها فوق بعضها لتوفير المساحة • سهل التنظيف: سطح داخلي أملس وتصميم عملي يسهل تنظيفه يدوياً أو في غسالة الأطباق • إغلاق محكم ومظهر أنيق: غطاء متناسق يمنع تسرب الروائح ويحافظ على طزاجة الطعام المواصفات • الماركة: الوطنية للبلاستيك • الموديل: ماستر لاين (Master Line) • عدد القطع: 3 قطع • الشكل: مربع • الخامة: بلاستيك آمن غذائياً وخالي من BPA • اللون: أبيض السعات والاستخدام • 600 مل: مناسب للجبن، المخللات، أو الكميات الصغيرة من الطعام • 1100 مل: مناسب للفواكه، السلطات، أو الوجبات المتوسطة • 1800 مل: مناسب للوجبات العائلية، الخضروات المجهزة، أو التخزين بكميات كبيرة الاستخدامات • تنظيم الثلاجة بشكل عملي • حفظ وتجميد الطعام • تحضير الوجبات مسبقاً • الحفاظ على الطعام طازجاً ومرتباً', N'El-Watania Master Line Plastic Refrigerator Set, 3 Pieces, Square Shape, Multi-Color', 110.00, NULL, N'ELG-38074270299397', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270299397/El-Watania+Master+Line+Plastic+Refrigerator+Set%2C+3+Pieces%2C+Square+Shape%2C+Multi-Color', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270299397');
