INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'علبة أرز بلاستيك الوطنية، 10 كيلو، مع كوب معياري، الوان متعددة', N'El Watania Plastic Rice Container, 10 KG, with Measuring Cup, Multiple Colors', N'el-watania-plastic-rice-container-10-kg-with-measuring-cup-multiple-colors-38074270299417', N'منظم الأرز من الوطنية حلاً عملياً وذكياً لكل مطبخ عصري، حيث يوفر سهولة الاستخدام وسرعة الوصول مع الحفاظ على الحبوب بعيداً عن الرطوبة والأتربة بفضل تصميمه المبتكر وخاماته الآمنة. المميزات • سعة كبيرة: بسعة 10 لتر يوفر مساحة كافية لتخزين الأرز، البقوليات، أو الدقيق بشكل منظم • تصميم بعجلات: مزود بعجلات خلفية قوية لسهولة الحركة داخل خزائن المطبخ حتى عند الامتلاء • غطاء ذكي: يحتوي على فتحة علوية قلابة تتيح الاستخدام السريع دون فتح الغطاء بالكامل • معيار مرفق: يأتي مع كوب معياري شفاف لتحديد الكميات بدقة وتقليل الهدر • شفافية عالية: جسم شفاف يتيح رؤية الكمية المتبقية بسهولة المواصفات • الماركة: الوطنية • الموديل: رايسر بوكس (Ricer Box) • السعة: 10 كيلو • الأبعاد: 21 × 36 × 24.5 سم • الخامة: بلاستيك آمن للاستخدام الغذائي • الألوان: متعدد (فوشيا، أزرق، موف، أحمر) الاستخدامات • تخزين الأرز والبقوليات • حفظ الدقيق والحبوب • تنظيم المطبخ بشكل عملي • الحفاظ على الطعام من الرطوبة والأتربة', N'El Watania Plastic Rice Container, 10 KG, with Measuring Cup, Multiple Colors', 138.00, NULL, N'ELG-38074270299417', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270299417/El+Watania+Plastic+Rice+Container%2C+10+KG%2C+with+Measuring+Cup%2C+Multiple+Colors', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270299417');
