INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'طقم توابل بورسلين من بلازا بغطاء بورسلين و حامل، 15 قطعة، أسود', N'Plaza Porcelain Seasoning Set with Porcelain Lid and Stand, 15 Pieces, Black', N'plaza-porcelain-seasoning-set-with-porcelain-lid-and-stand-15-pieces-black-38074270262193', N'تسوق واشتري الأن من موقع الغزاوي طقم توابل بورسلين من بلازا بغطاء بورسلين و حامل، 15 قطعة، بأفضل سعر محتويات طقم توابل بورسلين اسود:3 برطمانات توابل حجم كبير بغطاء.4 برطمانات توابل حجم متوسط بغطاء.1 حامل. مميزات طقم توابل بورسلين اسود:آمن في غسالة الأطباق.بورسلين صحي و آمن.طقم توابل بورسلين سهل التنظيف.سعر طقم توابل بورسلين اقتصادي مقدم من شركة بلازا.اللون: أسود.عدد القطع: 15 قطعة.طقم توابل بورسلين اسود من احدث اشكال اطقم التوابل.هذا الطقم الجميل يضفي لمسة من الرقي على أي مناسبة، فهو يجمع بين الأسلوب العملي والأناقة. إنه إضافة مثالية لمطبخك أو كهدية لمن تحب! لا تتردد في زيارة قسم ادوات مائده للحصول علي المزيد من صواني شاي، أطقم جاتوه، أطباق استانلس، أطباق خشبية، بولات بيركس المقدمة لك من موقع الغزاوي بأفضل الأسعار.', N'Plaza Porcelain Seasoning Set with Porcelain Lid and Stand, 15 Pieces, Black', 1020.00, NULL, N'ELG-38074270262193', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270262193/Plaza+Porcelain+Seasoning+Set+with+Porcelain+Lid+and+Stand%2C+15+Pieces%2C+Black', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270262193');
