INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'طقم توابل بورسلين 7 قطع مع حامل معدني، بينك* ذهبي، موديل 749-4', N'Porcelain Spice Set 7-Piece with Metal Holder, Pink*Gold, Model 749-4', N'porcelain-spice-set-7-piece-with-metal-holder-pink-gold-model-749-4-38074270293463', N'• تصميم أنيق وعصري: الطقم يتميز بتصميم بورسلين أنيق باللون البينك، مما يضيف لمسة فخمة إلى مطبخك • مواد عالية الجودة: البرطمانات مصنوعة من البورسلين المتين، الذي يحافظ على نكهة التوابل ويمنع الرطوبة • حماية فعالة للتوابل: الأغطية البورسلين تمنع تسرب الرطوبة وتحافظ على التوابل طازجة لفترة أطول • قاعدة ثابتة: الحامل المعدني يوفر قاعدة مستقرة وآمنة، مما يجعل الطقم سهل الاستخدام والتنظيم • سهولة الاستخدام والتنظيف: الطقم سهل الاستخدام ويمكن تنظيفه بسهولة، مما يجعله مثاليًا للاستخدام اليومي • توفير المساحة: التصميم المدمج لا يستهلك مساحة كبيرة، مما يجعله مناسبًا للمطابخ ذات المساحات الصغيرة• تنظيم التوابل: استخدم الطقم لتنظيم التوابل والأعشاب بطريقة أنيقة وسهلة الوصول. • تخزين فعال: الطقم مثالي لتخزين جميع أنواع البهارات والملح، مما يجعله دائمًا في متناول يدك أثناء الطهي. • عرض أنيق: يمكن وضع الطقم على المنضدة أو في رف المطبخ، حيث يضيف لمسة جمالية إلى المكان بفضل لونه الأسود الأنيق. • حفظ النكهة: يحافظ الطقم على نكهة التوابل بفضل الأغطية التي تمنع تسرب الرطوبة. • توفير المساحة: بفضل تصميمه المدمج، يمكن للطقم أن يتناسب بسهولة مع المساحات الصغيرة في المطبخ.محتويات الطقم - 4 برطمانات توابل صغيرة من البورسلين - 3 برطمانات توابل كبيرة من البورسلين - حامل معدني أنيق', N'Porcelain Spice Set 7-Piece with Metal Holder, Pink*Gold, Model 749-4', 1925.00, NULL, N'ELG-38074270293463', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270293463/Porcelain+Spice+Set+7-Piece+with+Metal+Holder%2C+Pink%2AGold%2C+Model+749-4', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270293463');
