INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'طقم توابل الاندلس ماربل، 12 برطمان مع حامل دوار 2 دور، رخامي الشكل لون أزرق فاتح', N'Al-Andalos Marble Spice Set, 12 Jars with 2-Tier Rotating Stand, Marble Pattern, Light Blue', N'al-andalos-marble-spice-set-12-jars-with-2-tier-rotating-stand-marble-pattern-light-blue-38074270293459', N'عدد القطع• 13 قطعة (12 علب توابل + استاند دوّار)التصميم• شكل مربّع• لون تركواز بنقشة رخامية مع عروق ذهبية• غطاء بلون ذهبي لامعالستاند• دوّار بزاوية 360° لسهولة الوصول• دورين (طبقتين)• مصنوع غالبًا من بلاستيك مقوّى أو معدن مطلي بالأسودعلب التوابل• جسم العلبة غالبًا زجاج أو بلاستيك سميك مع نافذة شفافة لرؤية المحتوى• سدادة سيليكون تركواز أعلى الغطاء للحفاظ على الإغلاق• تصميم محكم لمنع تسرب التوابلالسعة التقريبية لكل علبة• حوالي 150 – 200 ملالاستخدام• مناسب لحفظ الملح، الفلفل، الكمون، البابريكا، الكركم، الأعشاب وغيرهاالمميزات الظاهرة• تصميم أنيق وعصري مناسب للمطابخ الحديثة• موفّر للمساحة بفضل الستاند الدوّار• سهولة الوصول لكل التوابل دون الحاجة لتحريك العلب• نافذة شفافة تساعد على معرفة كمية التوابل المتبقية بسهولة', N'Al-Andalos Marble Spice Set, 12 Jars with 2-Tier Rotating Stand, Marble Pattern, Light Blue', 1050.00, NULL, N'ELG-38074270293459', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270293459/Al-Andalos+Marble+Spice+Set%2C+12+Jars+with+2-Tier+Rotating+Stand%2C+Marble+Pattern%2C+Light+Blue', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270293459');
