INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'طقم توابل بورسلين ألاندالس 7 قطع مع استاند ستانلس ستيل ذهبي، أبيض × ذهبي، موديل 111-A1', N'Al Andalos Porcelain Spice Set, 7 Pieces With Steel Stand, White × Gold, Model 111-A1', N'al-andalos-porcelain-spice-set-7-pieces-with-steel-stand-white-gold-model-111-a1-38074270297206', N'اسم المنتج: • طقم توابل بورسلين على حامل – 7 قطع – رقم المنتج 111 AN العلامة التجارية: • ألاندالس المواد الأساسية: • بورسلين عالي الجودة • حامل معدني متين • أغطية محكمة الغلق التصميم والهيكل: • تصميم أنيق وعصري يناسب مختلف ديكورات المطبخ • حامل معدني عملي يساعد على تنظيم البرطمانات بشكل مرتب • أغطية محكمة للحفاظ على المحتويات طازجة الأحجام المتوفرة: • طقم مكون من 7 قطع الكمية في العبوة: • 3 برطمانات كبيرة بغطاء محكم • 4 برطمانات صغيرة بغطاء محكم • حامل معدني أنيق اللون والمظهر الخارجي: • مظهر أنيق ولمسة راقية • مناسب لمختلف أنماط المطابخ الخصائص والاستخدام: • مصنوع من بورسلين متين وسهل التنظيف • مناسب لحفظ التوابل والبهارات الجافة • يمكن استخدامه لحفظ السكر والملح • سعة عملية ومناسبة للاستخدام اليومي', N'Al Andalos Porcelain Spice Set, 7 Pieces With Steel Stand, White × Gold, Model 111-A1', 2220.00, NULL, N'ELG-38074270297206', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270297206/Al+Andalos+Porcelain+Spice+Set%2C+7+Pieces+With+Steel+Stand%2C+White+%C3%97+Gold%2C+Model+111-A1', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270297206');
