INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'طقم توابل روما الوطنية، 8 قطع مع الاستاند', N'El Watania Roma Spice Set, 8 pieces with stand', N'el-watania-roma-spice-set-8-pieces-with-stand-38074270298041', N'ارتقِ بتجربة الطهي إلى مستوى جديد من التنظيم والأناقة مع طقم توابل روما الوطنية. هذا الطقم المبتكر هو الحل الأمثل لكل طاهٍ يبحث عن التميز والعملية، حيث يجمع بين التصميم العصري الجذاب والجودة الفائقة.لماذا تختار طقم توابل روما الوطنية؟تصميم "روما" الأنيق: مستوحى من البساطة الإيطالية الراقية، يتميز الطقم بعبوات زجاجية شفافة عالية الجودة تتيح لك رؤية التوابل بوضوح، مما يضيف لمسة جمالية فورية لأي مطبخ.إستاند منظم ومتين: يأتي الطقم مع إستاند عصري ومصمم بذكاء، يحمل العبوات الثمانية بشكل أنيق وموفر للمساحة. يضمن لك الوصول السريع والسهل لكل تابلة أثناء الطهي، مما يجعل المطبخ أكثر كفاءة.إحكام غلق ممتاز: العبوات مزودة بأغطية محكمة الإغلاق، مصممة للحفاظ على نكهة ورائحة التوابل طازجة وغنية لفترة أطول، وتحميها من الرطوبة والعوامل الخارجية.سعة مثالية ومتنوعة: مع 8 عبوات، يوفر الطقم مساحة كافية لمجموعة واسعة من التوابل الأساسية والخاصة، مما يلبي احتياجات مختلف الأطباق.سهولة الاستخدام والتنظيف: العبوات الزجاجية سهلة الملء والاستخدام، وقابلة للتنظيف بسهولة ، مما يوفر عليك الوقت والجهد.', N'El Watania Roma Spice Set, 8 pieces with stand', 220.00, NULL, N'ELG-38074270298041', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270298041/El+Watania+Roma+Spice+Set%2C+8+pieces+with+stand', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270298041');
