INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'طقم ملاحة زجاج، 2 قطعة ، حامل بمقبض، لون أبيض مزخرف، موديل 22-16', N'Glass Salt Shaker Set, 2 Pieces, Handle Holder, Decorative White Color, Model 22-16', N'glass-salt-shaker-set-2-pieces-handle-holder-decorative-white-color-model-22-16-38074270298384', N'التصميم الجمالي • النمط: تصميم رخامي أبيض أنيق مزين بعروق ذهبية عشوائية تضفي لمسة من الرقي. • التفاصيل: يحيط بالغطاء إطار ذهبي لامع يفصل بين الجزء العلوي والجسم الأساسي. • الشكل: العلب تأتي بتصميم مكعب بزوايا دائرية ناعمة، مما يسهل الإمساك بها. الخامات والمكونات • الهيكل: مصنوعاً من الزجاج عالي الجودة مع طبقة طلاء لامعة. • الشفافية: قاعدة العلب شفافة تماماً، مما يتيح رؤية نوع التوابل (ملح، فلفل، إلخ) ومتابعة الكمية المتبقية بسهولة. • الحامل (الستاند): قاعدة بيضاء متينة مخصصة لحمل العلبتين بشكل مستقر، مزودة بمقبض معدني طويل في المنتصف ينتهي برأس أبيض لسهولة النقل من المطبخ إلى طاولة الطعام. المواصفات الوظيفية • توزيع التوابل: الغطاء العلوي يحتوي على فتحات مخصصة لرش الملح أو الفلفل بدقة. • سهولة التنظيف: الأسطح الملساء تجعل عملية تنظيفه ومسحه من الخارج سهلة جداً. • الثبات: التصميم المخصص للقاعدة يضمن عدم انزلاق العلب أو سقوطها أثناء الحركة.', N'Glass Salt Shaker Set, 2 Pieces, Handle Holder, Decorative White Color, Model 22-16', 150.00, NULL, N'ELG-38074270298384', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270298384/Glass+Salt+Shaker+Set%2C+2+Pieces%2C+Handle+Holder%2C+Decorative+White+Color%2C+Model+22-16', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270298384');
