INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'طقم لانش بوكس ام ديزاين 1.6 + طقم طعام + زجاجة 650 مل ، برتقالى * فوشيا ، 75132', N'M-Design Lunch Box Set 1.6 , Food Set + Bottle 650 ml, Orange * Fuchsia, 75132', N'm-design-lunch-box-set-1-6-food-set-bottle-650-ml-orange-fuchsia-75132-38074270282354', N'طقم لانش بوكس من إم ديزاينطقم الغداء المكون من 3 قطع ضروري للآباء والطلاب المشغولين.يتضمن صندوق غداء خالٍ من مادة بيسفينول أ وآمن للطعام، وزجاجة مياه مانعة للتسرب، ومجموعة أدوات مائدة مكونة من 3 قطع داخل الصندوق.مع هذه المجموعة، يمكنك الاطمئنان إلى أن وجبتك وشرابك سيظلان آمنين وطازجين.صندوق غداء فريسكو سعة 1600 ملزجاجة مياه سعة 650 ملأدوات مائدةآمن للاستخدام في غسالة الأطباق والميكروويفآمن للطعام بنسبة 100%خالي من مادة بيسفينول أاللون:', N'M-Design Lunch Box Set 1.6 , Food Set + Bottle 650 ml, Orange * Fuchsia, 75132', 360.00, NULL, N'ELG-38074270282354', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270282354/M-Design+Lunch+Box+Set+1.6+%2C++Food+Set+%2B+Bottle+650+ml%2C+Orange+%2A+Fuchsia%2C+75132', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270282354');
