INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'طقم لانش بوكس ام ديزاين ، 1.1 لتر ، طقم طعام + زجاجة 500 مل ، تركواز برتقالى ، 75130', N'M-Design Lunch Box Set 1.1 , Food Set + Bottle 500 ml , Turquoise * Orange , 75130', N'm-design-lunch-box-set-1-1-food-set-bottle-500-ml-turquoise-orange-75130-38074270282358', N'طقم لانش بوكس ام ديزاينمجموعة الغداء المكونة من 3 قطع ضرورية للآباء والطلاب المشغولين.تتضمن صندوق غداء خالٍ من مادة BPA وآمن للطعام، وزجاجة مياه مانعة للتسرب، ومجموعة أدوات مائدة مكونة من 3 قطع داخل الصندوق.مع هذه المجموعة، يمكنك الاطمئنان إلى أن وجبتك وشرابك سيظلان آمنين وطازجين.صندوق غداء فريسكو سعة 1100 ملزجاجة مياه سعة 500 ملأدوات مائدةآمنة للاستخدام في غسالة الأطباق والميكروويفآمنة للطعام بنسبة 100%خالية من مادة BPAاللون: تركواز برتقالى', N'M-Design Lunch Box Set 1.1 , Food Set + Bottle 500 ml , Turquoise * Orange , 75130', 325.00, NULL, N'ELG-38074270282358', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270282358/M-Design+Lunch+Box+Set+1.1+%2C+Food+Set+%2B+Bottle+500+ml+%2C+Turquoise+%2A+Orange+%2C+75130', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270282358');
