INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'حافظة طعام 4 قطع مع شنطة حرارية وطقم مائدة - 26', N'4-piece food container set with thermal bag and tableware - 26', N'4-piece-food-container-set-with-thermal-bag-and-tableware-26-38074270299693', N'لانش بوكس حراري مع 4 علب هو طقم متكامل يشمل شنطة معزولة حراريًا و4 علب طعام منفصلة، وهي مصممة للحفاظ على الطعام ساخنًا أو باردًا، مع أغطية محكمة لمنع التسرب.&nbsp;شنطة حرارية: تساعد في حفظ درجة حرارة الطعام لفترة طويلة وتحتوي على بطانة عازلة.4 علب منفصلة: تتيح تنظيم الوجبات المختلفة بشكل مرتب في مكان واحد مصنوعة من خامات آمنة، وقابلة للتنظيف بسهولة. مصنوعة من خامات آمنة، وقابلة للتنظيف بسهولة.تصميم مانع للتسرب: الأغطية المحكمة تمنع انسكاب السوائل والروائح.خامات آمنة: غالبًا ما تكون خالية من مادة BPA وصحية للاستخدام اليومي.قابلية التسخين: بعض العلب يمكن وضعها في الميكروويف (بدون الغطاء).مناسب لعدة استخدامات: مثالي للاستخدام في العمل، المدرسة، النادي، أو الرحلات.عملي ومريح: تصميم أنيق وعملي مع مقبض مريح لحمله.محتويات الصندوق:4x حافظات طعام دائرية (Bento Boxes).1x حقيبة حرارية عازلة مزودة بسحاب.1x طقم أدوات مائدة1x محفظة صغيرة لأدوات المائدة.', N'4-piece food container set with thermal bag and tableware - 26', 375.00, NULL, N'ELG-38074270299693', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270299693/4-piece+food+container+set+with+thermal+bag+and+tableware+-+26', SYSUTCDATETIME()
