INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'طقم لانش بوكس حراري 1 حقيبة حرارية مع 3 علبة - لون بيج', N'Thermal Lunchbox Set: 1 thermal bag with 3 cans - Beige', N'thermal-lunchbox-set-1-thermal-bag-with-3-cans-beige-38074270300517', N'مصنوع من الفولاذ المقاوم للصدأ 304: يتميز صندوق الطعام هذا بمقاومته للصدأ ودرجات الحرارة العالية والأكسدة، مما يضمن نضارة الطعام وسلامته مع تقليل انبعاث المواد الضارة.أداء الإغلاق: بفضل تصميمه المحكم، يمنع هذا الصندوق التسربات والانسكابات بفعالية، ويحافظ على نضارة الحساء والسلطات والفواكه وغيرها، مما يمنحك راحة البال عند حمل وجباتك.يتسع صندوق الطعام المصنوع من الفولاذ المقاوم للصدأ لحصص كبيرة من الطعام للغداء أو العشاء أو النزهات الخارجية، ليلبي مختلف احتياجاتك.سهولة التنظيف: يقلل سطح الصندوق اللامع المصنوع من الفولاذ المقاوم للصدأ من بقايا الطعام، مما يجعل غسله سهلاً للغاية. سواءً تم غسله يدويًا أو في غسالة الأطباق، فإنه يبسط روتينك اليومي ويوفر لك الوقت والجهد.آمن وعملي: يقاوم صندوق الطعام المصنوع من الفولاذ المقاوم للصدأ درجات الحرارة العالية والمنخفضة، ولا يحتوي على أي مواد ضارة، ويوفر حماية إضافية لسلامة طعامك وطعام عائلتك، وهو مناسب للاستخدام المنزلي.', N'Thermal Lunchbox Set: 1 thermal bag with 3 cans - Beige', 490.00, NULL, N'ELG-38074270300517', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270300517/Thermal+Lunchbox+Set%3A+1+thermal+bag+with+3+cans+-+Beige', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270300517');
