INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'مج حراري ستانلس ستيل، 800 مل، أشكال متعددة، 242-1030', N'Stainless steel thermal mug, 800 ml, various shapes, 242-1030', N'stainless-steel-thermal-mug-800-ml-various-shapes-242-1030-38074270297353', N'مج حراري للسفر بتصميم دقيق وراحة فائقة. املأه دائمًا بالكامل للحصول على أفضل أداء.مصنوع من الفولاذ المقاوم للصدأ الآمن غذائيًا، غير قابل للكسر من الداخل والخارج، معزول بتفريغ الهواء.يحافظ على السوائل ساخنة أو باردة لمدة 8 إلى 12 ساعة. غطاء محكم الإغلاق مانع للتسرب، تصميم صغير الحجم بسعة كبيرة.مثالي للاستخدام في المنزل، المكتب، السفر، المستشفيات، المتاجر، المطاعم، الفنادق، وغيرها.الحجم: 800 مل، أبعاد المنتج (سم): ارتفاع 24 × عرض 8، الوزن: 370 غرام تقريبًا.', N'Stainless steel thermal mug, 800 ml, various shapes, 242-1030', 205.00, NULL, N'ELG-38074270297353', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270297353/Stainless+steel+thermal+mug%2C+800+ml%2C+various+shapes%2C+242-1030', SYSUTCDATETIME()
