INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'زجاجة رياضية بلاستيك ، سعة 1 لتر، مانعة للتسرب، ألوان متعددة، موديل 4273', N'Plastic Sports Bottle, 1 Liter, Leak-Proof, Multi-Color, Model 4273', N'plastic-sports-bottle-1-liter-leak-proof-multi-color-model-4273-38074270290417', N'زجاجة مياه "لا تستسلم أبدًا" المانعة للتسربزجاجة مياه كبيرة بسعة 1000 مل، مزودة بمؤشر وقت ومؤشر للأونصة، تحفزك على شرب المزيد من الماء، فهي كبيرة بما يكفي لتلبية حاجتك اليومية. مزودة بميزان قياس يساعدك على معرفة الكمية الفعلية للماء التي تشربها بسهولة ووضوح.مصنوعة من بلاستيك تريتان عالي الجودة صديق للبيئة، آمن غذائيًا، متين، خالٍ من مادة BPA والروائح الكيميائية، وصحي لشرب الماء يوميًا. زجاجة مياه كبيرة مزودة بمؤشر وقت بألوان زاهية متعددة تساعدك على زيادة كمية الماء التي تشربها يوميًا.', N'Plastic Sports Bottle, 1 Liter, Leak-Proof, Multi-Color, Model 4273', 132.00, NULL, N'ELG-38074270290417', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270290417/Plastic+Sports+Bottle%2C+1+Liter%2C+Leak-Proof%2C+Multi-Color%2C+Model+4273', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270290417');
