INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'زجاجة مياه رياضية مع منظم الحبوب والمكملات الغذائية، 450 مل، 3 طبقات قابلة للفك والتركيب، غطاء مانع للتسريب، بلاستيك، 4275', N'Sports Water Bottle with Pill and Supplement Organizer, 450ml, 3-Layer Removable Lid, Leak-Proof Cap, Plastic, 4275', N'sports-water-bottle-with-pill-and-supplement-organizer-450ml-3-layer-removable-lid-leak-proof-cap-plastic-4275-38074270290419', N'متعددة الاستخدامات ومريحة: توفر زجاجة المياه الرياضية المكونة من 3 طبقات أقصى درجات الراحة.قم بتخزين مسحوق البروتين الخاص بك في مكان واحد، وضع حبوبك في مكان آخر، ومشروبك في قسم الزجاجة الرئيسي. لا حاجة لحمل العديد من الحاويات؛ كل ما تحتاجه موجود في زجاجة واحدة أنيقة. يمكنك بسهولة إدارة المكملات الغذائية الخاصة بك وللابقاء على لياقتك.مقاومة للتسرب ومتينة: تم تصميم شيكر البروتين الخاص ليكون مقاومًا للتسرب، مما يوفر راحة البال أثناء التدريبات أو السفر.خلط بدون مجهود: قل وداعًا للكتل والتكتلات في مشروباتك حيث تضمن لك كرة الخلط المصنوعة من الفولاذ المقاوم للصدأ مزيجًا سلسًا ولذيذًا في كل مرة، مما يعزز تجربة الشرب.مصنوعة من بلاستيك عالي الجودة وخالي من البيسفينول أ، هذه الزجاجة متينة ومصممة تتحمل نمط حياتك النشط.مثالية لأي مشروب: في حين أنها مثالية للمشروبات الرياضية والعصائر، فإن هذه الزجاجة متعددة الاستخدامات يمكنها التعامل مع المشروبات المختلفة من الماء المنعش المليء بالفواكه إلى مشروب الطاقة المفضل لديك. صغيرة الحجم وخفيفة الوزن، مما يجعل من السهل حملها في حقيبة صالة الألعاب الرياضية أو حقيبة الظهر. سواء كنت تذهب إلى صالة الألعاب الرياضية أو تذهب في نزهة أو تسافر .', N'Sports Water Bottle with Pill and Supplement Organizer, 450ml, 3-Layer Removable Lid, Leak-Proof Cap, Plastic, 4275', 132.00, NULL, N'ELG-38074270290419', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270290419/Sports+Water+Bottle+with+Pill+and+Supplement+Organizer%2C+450ml%2C+3-Layer+Removable+Lid%2C+Leak-Proof+Cap%2C+Plastic%2C+4275', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270290419');
