INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'زجاجة مياه رياضية بلاستيك ، سعة 1 لتر ، ازرق ، 4285', N'Plastic Sports Water Bottle, 1 Liter, Blue , 4285', N'plastic-sports-water-bottle-1-liter-blue-4285-38074270290430', N'استمتع بشرب خالٍ من المتاعب أثناء التنقل مع شفاطة مدمجة تضمن سهولة الوصول إلى مشروبك دون انقلاب أو انسكاب .مثالية للتدريبات أو ممارسة الأنشطة الخارجية.تصميمها الأنيق وحجمها المحمول يجعلها الرفيق المثالي في أي مكان .تجعلك متميزًا بمظهرها العصري مع الحفاظ على رطوبة جسمك أثناء التمارين أو المشي لمسافات طويلة أو الروتين اليومي . مصنوعة من مواد عالية الجودة ، مصممة لتحمل الاستخدام اليومي . هيكلها المتين يجعلها مرنة ضد الصدمات وتدوم طويلًا .صُممت هذه الزجاجة الملائمة لصالة الألعاب الرياضية مع وضع اللياقة البدنية في الاعتبار، وتحتوي على حزام مريح للحمل بدون مجهود .', N'Plastic Sports Water Bottle, 1 Liter, Blue , 4285', 199.00, NULL, N'ELG-38074270290430', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270290430/Plastic+Sports+Water+Bottle%2C+1+Liter%2C+Blue+%2C+4285', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270290430');
