INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'زجاجة مياه رياضية 800 مللي، بلاستيك * استانلس ستيل، متعددة الألوان، موديل 42-137', N'Sports Water Bottle 800ml, Plastic * Stainless Steel, Multicolor, Model 42-138', N'sports-water-bottle-800ml-plastic-stainless-steel-multicolor-model-42-138-38074270291247', N'٨٠٠ مل من الماء للحفاظ على ترطيبك أثناء التمارين الشاقة والأنشطة الخارجيةألوان زاهية متنوعة: سيبدو نظام الترطيب هذا أكثر حيوية ومتعة بفضل ألوانه الزاهية المتنوعةهيكل متين: مصنوع من بلاستيك عالي الجودة، مما يضمن طول العمر والمتانة حتى في الظروف القاسيةتصميم مانع للتسرب: يمكنك وضعه بثقة في حقيبتك أو حقيبة ظهرك بفضل غطاءه المحكم الذي يمنع الانسكابات والتسرباتسهل الحمل وخفيف الوزن، هذا الجهاز مثالي للأنشطة الخارجية مثل المشي لمسافات طويلة والرياضة والنادي الرياضي وغيرها من الأنشطة المماثلة', N'Sports Water Bottle 800ml, Plastic * Stainless Steel, Multicolor, Model 42-138', 120.00, NULL, N'ELG-38074270291247', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270291247/Sports+Water+Bottle+800ml%2C+Plastic+%2A+Stainless+Steel%2C+Multicolor%2C+Model+42-138', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270291247');
