INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'زجاجة مياه تانك ستانلس ستيل خالية من مادة BPA، معزولة حراريًا، مانع للتسريب، كحلي ، 350 مللي', N'Tank Water Bottle, Stainless Steel, Bpa-free, Insulated, Leak-proof, Navy Blue , 350 Ml', N'tank-water-bottle-stainless-steel-bpa-free-insulated-leak-proof-navy-blue-350-ml-38074270293699', N'عزل مزدوج الجدار بتقنية التفريغ الهوائي لضمان أقصى احتفاظ بدرجة الحرارة لمدة تصل الى 24 ساعة.جدار داخلي من الستانلس ستيل 304 لتعزيز المتانة، مقاومة الصدأ، وأداء آمن للطعام و المياهالسعة: 350 مل.غطاء شرب سهل الاستخدام لتجربة شرب سلسة ومريحة أثناء التنقل.تصميم بمقبض سيليكون لمسك مريح وثابت وسهولة في الحمل.قاعدة مانعة للانزلاق لتثبيت الزجاجة على مختلف الأسطح.تصميم مضاد للتسريب لمنع الانسكاب وحماية مقتنياتك من البلل.طلاء خارجي مقاوم للخدوش لمتانة تدوم طويلاً.تناسب حاملات الأكواب في السيارات لسهولة التنقل.تصميم قوي ومتين يتحمل الاستخدام اليومي المكثف.', N'Tank Water Bottle, Stainless Steel, Bpa-free, Insulated, Leak-proof, Navy Blue , 350 Ml', 520.00, NULL, N'ELG-38074270293699', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270293699/Tank+Water+Bottle%2C+Stainless+Steel%2C+Bpa-free%2C+Insulated%2C+Leak-proof%2C+Navy+Blue+%2C+350+Ml', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270293699');
