INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'زجاجة مياه تانك موڤ، 550 مل، زجاجة ستانلس ستيل، معزولة حراريًا، مانع للتسريب، أزرق سماوي', N'Tank Move Water Bottle, 550ml, Stainless Steel Bottle, Thermal Insulated, Leak Proof, Sky Blue', N'tank-move-water-bottle-550ml-stainless-steel-bottle-thermal-insulated-leak-proof-sky-blue-38074270293705', N'عزل مزدوج الجدار بتقنية التفريغ الهوائي لضمان أقصى احتفاظ بدرجة الحرارة لمدة تصل الى 24 ساعة.جدار داخلي من الستانلس ستيل 304 لتعزيز المتانة، مقاومة الصدأ، وأداء آمن للطعام و المياهالسعة: 550 مل.غطاء شرب سهل الاستخدام لتجربة شرب سلسة ومريحة أثناء التنقل.تصميم بمقبض سيليكون لمسك مريح وثابت وسهولة في الحمل.قاعدة مانعة للانزلاق لتثبيت الزجاجة على مختلف الأسطح.تصميم مضاد للتسريب لمنع الانسكاب وحماية مقتنياتك من البلل.طلاء خارجي مقاوم للخدوش لمتانة تدوم طويلاً.تناسب حاملات الأكواب في السيارات لسهولة التنقل.تصميم قوي ومتين يتحمل الاستخدام اليومي المكثف.', N'Tank Move Water Bottle, 550ml, Stainless Steel Bottle, Thermal Insulated, Leak Proof, Sky Blue', 625.00, NULL, N'ELG-38074270293705', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270293705/Tank+Move+Water+Bottle%2C+550ml%2C+Stainless+Steel+Bottle%2C+Thermal+Insulated%2C+Leak+Proof%2C+Sky+Blue', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270293705');
