INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'زجاجة مياه تانك ماغنت ستانلس ستيل خالية من مادة BPA، معزولة حراريًا، مانع للتسريب، كريمي ، 1000 مللي', N'Tank Magnet Stainless Steel Water Bottle, Bpa-free, Insulated, Leak-proof, Creamy , 1000 Ml', N'tank-magnet-stainless-steel-water-bottle-bpa-free-insulated-leak-proof-creamy-1000-ml-38074270293724', N'عزل مزدوج الجدار بتقنية التفريغ الهوائي لضمان أقصى احتفاظ بدرجة الحرارة لمدة تصل الى 24 ساعة.جدار داخلي من الستانلس ستيل 304 لتعزيز المتانة، مقاومة الصدأ، وأداء آمن للطعام و المياهالسعة: 1000 مل.غطاء شرب سهل الاستخدام لتجربة شرب سلسة ومريحة أثناء التنقل.تصميم بمقبض سيليكون لمسك مريح وثابت وسهولة في الحمل.قاعدة مانعة للانزلاق لتثبيت الزجاجة على مختلف الأسطح.تصميم مضاد للتسريب لمنع الانسكاب وحماية مقتنياتك من البلل.طلاء خارجي مقاوم للخدوش لمتانة تدوم طويلاً.تناسب حاملات الأكواب في السيارات لسهولة التنقل.تصميم قوي ومتين يتحمل الاستخدام اليومي المكثف.', N'Tank Magnet Stainless Steel Water Bottle, Bpa-free, Insulated, Leak-proof, Creamy , 1000 Ml', 999.00, NULL, N'ELG-38074270293724', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270293724/Tank+Magnet+Stainless+Steel+Water+Bottle%2C+Bpa-free%2C+Insulated%2C+Leak-proof%2C+Creamy+%2C+1000+Ml', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270293724');
