INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'زجاجة مياه ستانلس ستيل خالية من مادة BPA، معزولة حراريًا، مانع للتسريب، متعددة الألوان، 620 مللي، موديل 1589', N'Stainless steel water bottle, BPA-free, thermally insulated, leak-proof, multi-colored, 620ml, model 1589', N'stainless-steel-water-bottle-bpa-free-thermally-insulated-leak-proof-multi-colored-620ml-model-1589-38074270298411', N'اسم المنتج: • كوب حراري ستانلس ستيل 304 – سعة 620 مل السعة: • 620 مل التصميم: • تصميم عصري وأنيق مناسب للاستخدام اليومي المواد الأساسية: • المادة الرئيسية: ستانلس ستيل 304 عالي الجودة • مقاوم للصدأ والتآكل وآمن صحيًا الهيكل والتفاصيل: • يدعم طريقتين للشرب (باستخدام الشفاط أو الشرب المباشر) • مزود بحزام/مقبض مريح للحمل اللون والمظهر الخارجي: • مظهر أنيق وعصري الخصائص والمميزات: • صديق للبيئة • سهل التنظيف • متين وطويل العمر • مناسب للاستخدام اليومي • مرن في طريقة الاستخدام حسب الحاجة الأداء: • يحافظ على المشروبات الساخنة لمدة 6–8 ساعات تقريبًا • يحافظ على المشروبات الباردة لأكثر من 12 ساعة الاستخدام: • مناسب للقهوة، الشاي، والمشروبات الباردة طوال اليوم • مثالي للعمل، الدراسة، أو التنقل محتويات العبوة: • كوب حراري • علبة تغليف أنيقة (مناسبة للهدايا)', N'Stainless steel water bottle, BPA-free, thermally insulated, leak-proof, multi-colored, 620ml, model 1589', 250.00, NULL, N'ELG-38074270298411', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270298411/Stainless+steel+water+bottle%2C+BPA-free%2C+thermally+insulated%2C+leak-proof%2C+multi-colored%2C+620ml%2C+model+1589', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270298411');
