INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'زمزمية اطفال جوي 1000 مللي، شفاطة داخلية، ألوان متعددة، موديل 3089', N'Joe Kids Bottle 1000ml, Built-in Straw, Multi-Color, Model 3089', N'joe-kids-bottle-1000ml-built-in-straw-multi-color-model-3089-38074270291336', N'الخامة: بلاستيك، آمن غذائيًا، متين، قوي، خالٍ من مادة BPA، مقاوم للكسر، مقاوم للصدأ، سيليكون، عديم الرائحة، أملس، آمن.تصميم بسعة كبيرة: تتميز زجاجة الماء هذه بسعة كبيرة، مما يعزز ترطيب طفلك ومناعته، كما أن تصميمها أنيق وعملي، ليتمكن طفلك من شرب الماء في أي وقت وفي أي مكان!تصميم أنيق: تتميز زجاجة الماء هذه بلونها الزاهي وتصميمها الشبابي الذي يجذب الأطفال، فهي تجمع بين العملية والأناقة!سهلة الحمل: تأتي زجاجة الماء مع أحزمة شريطية مريحة لحمايتها، ويمكن لطفلك تعليقها على حقيبة المدرسة، وهي عملية للسفر والنزهات!تصميم عملي على شكل مصاصة: تتميز زجاجة الماء هذه بتصميم مصاصة سيليكون مدمج، مما يساعد الأطفال على شرب الماء بسهولة وتطوير عادات شرب جيدة، كما أنها مزودة بغطاء متين يمنع انسكاب الماء على الملابس.السعة: لتر واحدالمقاس: ١٩ سم × ١٢ سم', N'Joe Kids Bottle 1000ml, Built-in Straw, Multi-Color, Model 3089', 340.00, NULL, N'ELG-38074270291336', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270291336/Joe+Kids+Bottle+1000ml%2C+Built-in+Straw%2C+Multi-Color%2C+Model+3089', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270291336');
