INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'طقم كوبايات زجاج بلينك ماكس موديل Y4203 6 قطع سعة 300 مللي- لون شفاف', N'Blinkmax Glass Set Model Y4203 6 Pieces 300ml Capacity-Clear Color', N'blinkmax-glass-set-model-y4203-6-pieces-300ml-capacity-clear-color-38074270299633', N'اسم المنتج • طقم أكواب "بلينك ماكس" الكريستالية – فخامة التقديم في كل تفصيلة العلامة التجارية • Blink Max (بلينك ماكس) الخامات الأساسية • مصنوع من زجاج عالي الجودة • زجاج مقوى مقاوم للخدش والبهتان • قاعدة سميكة لزيادة المتانة والثبات التصميم والهيكل • تصميم عصري فاخر بنقوش هندسية بارزة تشبه "التاج" • قاعدة سميكة تعكس الضوء بشكل مميز • حواف مصقولة ناعمة لراحة أثناء الشرب • هيكل متوازن يمنح ثباتاً ممتازاً على الطاولة الأحجام المتوفرة • السعة: 300 مل • الارتفاع: 101 ملم • القطر العلوي: 86 ملم • القطر السفلي: 63 ملم الكمية في العبوة • طقم مكون من 6 أكواب اللون والمظهر الخارجي • زجاج شفاف فائق النقاء • تأثير كريستالي يعكس الضوء بشكل جذاب الخصائص والاستخدام • مثالي لتقديم المياه، العصائر، والمشروبات الغازية • مناسب للاستخدام اليومي والمناسبات الرسمية • تصميم أنيق يناسب المنازل والفنادق والمطاعم • قاعدة ثابتة تقلل من احتمالية الانزلاق • يتحمل الاستخدام المكثف دون فقدان المظهر الفاخر إرشادات العناية • آمن للاستخدام في غسالة الأطباق • سهل التنظيف ولا يتأثر بالمنظفات • يُفضل التعامل بحذر للحفاظ على سلامة الزجاج', N'Blinkmax Glass Set Model Y4203 6 Pieces 300ml Capacity-Clear Color', 255.00, NULL, N'ELG-38074270299633', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270299633/Blinkmax+Glass+Set+Model+Y4203+6+Pieces+300ml+Capacity-Clear+Color', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270299633');
