INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'طقم كاسات أيس كريم باشابتشي رين، 2 قطعة، سعة 240 مللي ، لون شفاف، موديل 51809', N'Pasabahce Rain Ice Cream Cup Set, 2 Pieces, 240ml Capacity, Clear Color, Model 51809', N'pasabahce-rain-ice-cream-cup-set-2-pieces-240ml-capacity-clear-color-model-51809-38074270297126', N'الاسم والعلامة التجارية • الاسم: Pasabahce Rain Ice 240ml • العلامة التجارية: Pasabahce الاستخدام والغرض • الوظيفة: مثالية لعرض مجموعة متنوعة من الحلويات الباردة مثل الآيس كريم، السندويشات، الموس، البودينغ وسلطات الفواكه • الاستخدام: مناسبة للاستخدام المهني في البارات والمقاهي والمطاعم، وأيضًا للاستخدام المنزلي، مع إبراز المحتوى بصريًا دون التأثير على عرض الحلويات السعة والأبعاد • السعة: 240 مل • الأبعاد: 91 مم (ارتفاع) × 205 مم (عرض) × 103 مم (عمق) • النسب الكلاسيكية تجعلها مناسبة لقوائم حلويات متنوعة الخامة والتصميم • المادة: زجاج صودا-جير عالي الجودة • التصميم: نقشة Rain المنقوشة والملموسة التي تضيف لمسة جمالية لأي عرض للحلويات • الزجاج الشفاف يوفر وضوحًا ممتازًا لإبراز الألوان والقوام الزاهي للحلويات العناية والطقم • العناية: آمن للغسل في غسالة الصحون لسهولة التنظيف • الطقم: متوفر في عبوة من 24 قطعة • مصمم لأداء موثوق يحافظ على الأناقة والمتانة بعد كل استخدام الميزات • تصميم ملموس فريد يعزز عرض الحلويات • الحجم مثالي لتقديم السندويشات، الموس، سلطات الفواكه والآيس كريم التقليدي • جودة تصنيع عالية توفر وضوحًا ممتازًا • آمن للغسل في غسالة الصحون لسهولة الصيانة', N'Pasabahce Rain Ice Cream Cup Set, 2 Pieces, 240ml Capacity, Clear Color, Model 51809', 165.00, NULL, N'ELG-38074270297126', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270297126/Pasabahce+Rain+Ice+Cream+Cup+Set%2C+2+Pieces%2C+240ml+Capacity%2C+Clear+Color%2C+Model+51809', SYSUTCDATETIME()
