INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'طقم أكواب زجاج، 6 قطع، مزخرف ومنقوش، لون عسلي، 154', N'Glass cup set, 6 pieces, decorative and embossed, honey color, 154', N'glass-cup-set-6-pieces-decorative-and-embossed-honey-color-154-38074270297387', N'طقم أكواب زجاجية بتصميم "لحاء الشجر" الفاخر - 6 قطع (لون عنبري دافئ)ارتقِ بتجربة تناول مشروباتك المفضلة مع هذا الطقم الاستثنائي!أضف لمسة من الدفء والأناقة المستوحاة من سحر الطبيعة إلى مائدتك مع طقم الأكواب الزجاجية المكون من 6 قطع. صُنع هذا الطقم خصيصاً لأصحاب الذوق الرفيع، ليجمع بين الفخامة، والمتانة، والتصميم الفني الفريد الذي يخطف الأنظار.مميزات المنتج:تصميم حصري وملمس بارز: يتميز بسطح خارجي منقوش يحاكي جمال "لحاء الشجر" أو التكوينات الصخرية الطبيعية، مما يمنحه مظهراً ريفياً عصرياً وملمساً رائعاً عند الإمساك به.لون عنبري ساحر: درجة لونية دافئة وجذابة تعكس الضوء بشكل جميل، وتضفي طابعاً كلاسيكياً وراقياً على أي مشروب تقدمه.حواف انسيابية مموجة: لمسة نهائية غير تقليدية تبتعد عن الحواف المستقيمة المعتادة، لتعزز من الطابع الطبيعي والفني للكوب.تصميم ذكي ومتين للمقبض يضمن لك إمساكاً مريحاً وآمناً، حتى مع المشروبات الساخنة جداً.جودة عالية وعملية: زجاج سميك متين يتحمل الاستخدام اليومي، ومثالي لجميع أنواع المشروبات (القهوة، الشاي، الأعشاب، أو حتى المشروبات الباردة).', N'Glass cup set, 6 pieces, decorative and embossed, honey color, 154', 245.00, NULL, N'ELG-38074270297387', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270297387/Glass+cup+set%2C+6+pieces%2C+decorative+and+embossed%2C+honey+color%2C+154', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270297387');
