INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'طقم أكواب لومينارك فليم تونجان جرين، 6 قطع، 280 مل، شفاف', N'Luminarc Flame Tongan Green Glass Set, 6 Pieces, 280ml, Clear', N'luminarc-flame-tongan-green-glass-set-6-pieces-280ml-clear-38074270297971', N'طقم أكواب لومينارك فلام تونجان جرين (6 قطع) – الأناقة العصرية على مائدتكأضف لمسة من الرقي والحيوية إلى تجربة تقديم المشروبات مع طقم أكواب "لومينارك فلام تونجان جرين" (Luminarc Flame Tongan Green).يتميز هذا الطقم بتصميم فريد يجمع بين نقاء الزجاج وجمال التفاصيل المستوحاة من الطبيعة، ليكون الخيار الأمثل للضيافة الفاخرة والاستخدام اليومي المريح.المميزات:تصميم عصري وجذاب: يتألق كل كوب بلمسة فنية مميزة على شكل ورقة شجر مزدوجة بنقشة التمويه الأخضر (تونجان جرين)، مما يكسر روتين الأكواب التقليدية ويضفي طابعاً شبابياً وأنيقاً على مائدتك.جودة فرنسية استثنائية: مصنوع من زجاج لومينارك شديد النقاء والشفافية (خالٍ من الرصاص 0%)، مما يبرز لون المشروبات بداخله ويضمن لك لمعاناً لا يبهت مع مرور الزمن.سعة مثالية (280 مل): الحجم العملي الأنسب لتقديم الماء، العصائر الطازجة، المشروبات الغازية، والكوكتيلات المنعشة.قاعدة ثابتة ومسكة مريحة: يتميز الكوب بتصميم هندسي ذكي يبدأ بقاعدة شبه مربعة توفر ثباتاً ممتازاً على الأسطح، وينتهي بحواف دائرية ناعمة لضمان راحة تامة عند الشرب.عملي ومتين: مصمم ليتحمل الاستخدام اليومي المستمر، وهو آمن تماماً للغسيل في غسالة الأطباق دون أن يفقد رونقه أو تصميماته المطبوعة.طقم متكامل للضيافة: يأتي الطقم مكوناً من 6 قطع متطابقة، مما يجعله مثالياً لتجمعات العائلة والأصدقاء.', N'Luminarc Flame Tongan Green Glass Set, 6 Pieces, 280ml, Clear', 365.00, NULL, N'ELG-38074270297971', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270297971/Luminarc+Flame+Tongan+Green+Glass+Set%2C+6+Pieces%2C+280ml%2C+Clear', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270297971');
