INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'طقم شاي سيراميك فلامنجو، 13 قطعة، ستاند معدني، ألوان متعددة، موديل 2148-268', N'Flamingo Ceramic Tea Set, 13 Pieces, Metal Stand, Multi-Color, Model 2148-268', N'flamingo-ceramic-tea-set-13-pieces-metal-stand-multi-color-model-2148-268-38074270296523', N'اسم المنتج: طقم أكواب شاي/قهوة سيراميك بتصميم فلامنجو وإسكندنافي • الخامة والتصميم • مصنوع من مادة السيراميك عالي الجودة، متين وآمن للاستخدام لفترة طويلة. • تصميم عصري ومبتكر مع خطوط جميلة وأوروبية تجعل الكوب جذابًا. • تصميم مزخرف على الكوب والصحن يمنح الطقم لمسة ديكور أنيقة على المائدة. • الاستخدامات • مناسب لمختلف المناسبات: المنزل، المكتب، المقهى، المطاعم. • يمكن استخدامه لتقديم القهوة، الشاي، الحليب، الشوكولاتة الساخنة، الماء، العصائر، والمشروبات الساخنة أو الباردة الأخرى. • الخيار الأمثل كهدية للعائلة والأصدقاء والعمال. • الأبعاد والسعات • أبعاد الكوب: 15 × 8 × 2 سم / 5.89 × 3.14 × 0.79 إنش • أبعاد الصحن: 11 × 6.5 × 6 سم / 4.33 × 2.56 × 2.36 إنش • وزن الكوب: 222 جرام • عدد القطع في العبوة • 1 × كوب • 1 × صحن', N'Flamingo Ceramic Tea Set, 13 Pieces, Metal Stand, Multi-Color, Model 2148-268', 579.00, NULL, N'ELG-38074270296523', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270296523/Flamingo+Ceramic+Tea+Set%2C+13+Pieces%2C+Metal+Stand%2C+Multi-Color%2C+Model+2148-268', SYSUTCDATETIME()
