INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'طقم قهوة بورسلين الاندلس ، 12 قطعة، لون بينك بحواف ورسومات ذهبية، موديل 3131', N'Al Andalos Porcelain Coffee Set, 12 Pieces, Pink Color With Gold Trim And Designs, Model 3134', N'al-andalos-porcelain-coffee-set-12-pieces-pink-color-with-gold-trim-and-designs-model-3134-38074270293461', N'المادة الأساسية• أكواب وصحون مصنوعة من بورسلين عالي الجودةالتصميم والهيكل• تصميم أنيق باللون الوردي مع زخارف أوراق شجر ذهبية• حواف ذهبية لامعة تضيف لمسة فخامة• أكواب قهوة صغيرة مناسبة لتقديم القهوة العربية أو التركية• صحون متناسقة بنفس اللون والزخرفة• تصميم مناسب للتقديم في الضيافة والمناسباتالأحجام والسعة التقريبية• حجم فنجان صغير مناسب لتقديم القهوة• سعة مناسبة للقهوة العربية أو التركيةعدد القطع في الطقم• 6 فناجين قهوة• 6 صحون فناجين• إجمالي القطع: 12 قطعةاللون والمظهر الخارجي• لون أساسي الوردي • رسومات ورق شجر باللون الذهبي• حواف ذهبية أنيقة• مظهر فاخر مناسب للتقديمالخصائص والاستخدام• مناسب لتقديم القهوة العربية أو التركية• تصميم أنيق يضيف لمسة جمالية للمائدة• خامة بورسلين متينة تتحمل الاستخدام اليومي• مناسب للاستخدام المنزلي أو الضيافة• يمكن استخدامه أيضًا كهدية للمناسبات المختلفة', N'Al Andalos Porcelain Coffee Set, 12 Pieces, Pink Color With Gold Trim And Designs, Model 3134', 1400.00, NULL, N'ELG-38074270293461', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270293461/Al+Andalos+Porcelain+Coffee+Set%2C+12+Pieces%2C+Pink+Color+With+Gold+Trim+And+Designs%2C+Model+3134', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270293461');
