INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'طقم قهوة بورسلين الاندلس شكل وزة 12 قطعة 6 فنجان و6 اطباق-لون أسود', N'Al-Andalos Porcelain Coffee Set, Goose Shape, 12 Pieces 6 Cups And 6 Plates- Black', N'al-andalos-porcelain-coffee-set-goose-shape-12-pieces-6-cups-and-6-plates-black-38074270299666', N'الاسم • طقم قهوة بورسلين شكل الأوزة النوع • طقم تقديم قهوة الخامة • بورسلين عالي الجودة • يحتفظ بدرجة حرارة المشروبات لفترة أطول • سطح لامع ومقاوم للاستخدام اليومي التصميم والهيكل • تصميم مبتكر مستوحى من شكل الأوزة • الفنجان مع الطبق يشكلان هيئة طائر الأوز بشكل انسيابي • طابع فني يجمع بين الفخامة والعصرية • تفاصيل دقيقة تعزز الجانب الجمالي للطقم الألوان والتشطيب • لون أسود أنيق • نقوش ذهبية فاخرة • عبارة "Forever Love You" بتصميم رومانسي مميز • لمسات نهائية لامعة تعكس الفخامة المكونات • 6 فناجين قهوة • 6 أطباق تقديم الاستخدام • مناسب للقهوة العربية أو التركية أو الإسبريسو • مثالي للاستخدام العائلي أو استقبال الضيوف • مناسب للتقديم في المناسبات الخاصة الخصائص • يحافظ على حرارة القهوة لفترة جيدة • تصميم ديكوري يمكن عرضه كقطعة فنية • سهل التنظيف والاستخدام اليومي الهدية • مناسب جدًا للهدايا • مثالي لحفلات الزفاف والمناسبات السعيدة • تصميم غير تقليدي يضيف قيمة جمالية للهدية', N'Al-Andalos Porcelain Coffee Set, Goose Shape, 12 Pieces 6 Cups And 6 Plates- Black', 1720.00, NULL, N'ELG-38074270299666', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270299666/Al-Andalos+Porcelain+Coffee+Set%2C+Goose+Shape%2C+12+Pieces+6+Cups+And+6+Plates-+Black', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270299666');
