INSERT INTO [dbo].[Products] ([NameAr], [NameEn], [Slug], [DescriptionAr], [DescriptionEn], [Price], [OriginalPrice], [SKU], [StockQuantity], [CategoryId], [IsFeatured], [IsActive], [Material], [Origin], [SourceUrl], [ImportedAt])
SELECT N'براد شاي بيركس الاندالس، سعة 1.4 لتر، مصفاه داخلية، لون شفاف، موديل 0814', N'Al-Andalos Pyrex tea pot with porcelain handle , 1.4l, transparent, 0814', N'al-andalos-pyrex-tea-pot-with-porcelain-handle-1-4l-transparent-0814-38074270274267', N'اسم المنتج: براد شاي بايركس الأندلس بمصفاة داخليةالسعة: 1.4 لتر • الخامة والتصميم• مصنوع من زجاج بايركس عالي الجودة المقاوم للحرارة.• تصميم شفاف أنيق يتيح رؤية لون الشاي أثناء التحضير.• تصميم عملي يناسب الاستخدام اليومي والضيافة.• المصفاة والمقبض• مزود بـ مصفاة داخلية لفصل أوراق الشاي أو الأعشاب بسهولة.• مقبض عازل للحرارة لسهولة الحمل والصب بأمان دون حروق.• غطاء محكم يساعد على الحفاظ على حرارة المشروب.• الاستخدامات• مثالي لتحضير الشاي، الأعشاب، المشروبات الساخنة، والمشروبات المنقوعة.• مناسب للاستخدام في المنزل، المكاتب، والجلسات العائلية.• الميزات العملية• سهل التنظيف بفضل الزجاج الأملس والمصفاة القابلة للإزالة.• آمن للاستخدام مع الماء الساخن.• يجمع بين الأناقة والعملية في منتج واحد.', N'Al-Andalos Pyrex tea pot with porcelain handle , 1.4l, transparent, 0814', 775.00, NULL, N'ELG-38074270274267', 30, @KitchenCategoryId, 0, 1, NULL, N'Elghazawy', N'https://elghazawy.com/ar/product/38074270274267/Al-Andalos+Pyrex+tea+pot+with+porcelain+handle+%2C+1.4l%2C+transparent%2C+0814', SYSUTCDATETIME()
WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Products] WHERE [SKU] = N'ELG-38074270274267');
